    texts: [
      { title: "प्रारंभिक पहुँच", feynman: "कर्मचारी ने बेसुध होकर खोली एक फ़िशिंग ईमेल — यही वह स्विच थी जिसने किले का दरवाज़ा खोल दिया। मैलवेयर चला, और हमलावर का रिमोट टर्मिनल सक्रिय हो गया।", expert: "स्पियर फ़िशिंग के माध्यम से Initial Access। C2 सर्वर से कनेक्शन स्थापित हुआ।", defTooltip: "👀 अज्ञात बाहरी IP से रिमोट एक्सेस ट्रैफिक का पता चला।", hackerLog: null, terms: [{name:"Spear Phishing", desc:"किसी विशिष्ट व्यक्ति को निशाना बनाकर दुर्भावनापूर्ण अटैचमेंट या लिंक भेजने वाला लक्षित ईमेल हमला।"}, {name:"C2 Server", desc:"हमलावर द्वारा संक्रमित PC को दूरस्थ रूप से नियंत्रित करने और आदेश देने के लिए उपयोग किया जाने वाला केंद्रीय सर्वर।"}] },
      { title: "प्रारंभिक घुसपैठ", feynman: "घुसपैठिया शीशे में देखता है। 'क्या मैं आम नागरिक के कपड़ों में हूँ या जनरल की वर्दी में?' वह अपनी वर्तमान पहुँच का स्तर जानना चाहता है।", expert: "अपहृत सत्र की विशेषाधिकार स्तर और समूह सदस्यता की पहचान करना — विशेषाधिकार वृद्धि रणनीति बनाना।", defTooltip: "⚠️ एक सामान्य उपयोगकर्ता ने संदिग्ध कमांड (whoami /all) चलाकर सिस्टम अधिकारों की जाँच की।", hackerLog: { title: "whoami_priv_check.txt", lines: [ { log: "USER INFORMATION\n----------------\nUser Name: CORP\\Alice", desc: "💡 अपहृत खाते की पहचान की पुष्टि कर रहा है।" }, { log: "GROUP INFORMATION\n...\nBUILTIN\\Users", desc: "💡 समूह सदस्यता जाँचकर पहुँच सीमा निर्धारित कर रहा है।" }, { log: "PRIVILEGES INFORMATION\n...\nSeChangeNotifyPrivilege", desc: "💡 एडमिन तक पहुँच बढ़ाने के लिए शोषण योग्य विशेषाधिकार ढूँढ रहा है।" } ] }, terms: [ { name: "whoami /all", desc: "विंडोज कमांड जो वर्तमान उपयोगकर्ता का नाम, समूह और सभी विशेषाधिकार दिखाती है।" }, { name: "Privilege Escalation", desc: "हैकिंग चरण जहाँ सामान्य उपयोगकर्ता खाते को सर्वोच्च सिस्टम व्यवस्थापक अधिकारों तक बढ़ाया जाता है।" } ] },
      { title: "आंतरिक नेटवर्क टोही", feynman: "किले को लूटने के लिए नक्शा चाहिए। हैकर अपना कंपास और नक्शा निकालकर राजा (केंद्रीय सर्वर) के महल का स्थान खोजता है।", expert: "सबनेट रेंज और DNS (आमतौर पर Domain Controller) IP की पहचान करके लक्ष्य की नेटवर्क स्थिति को मैप करना।", defTooltip: "🔍 आंतरिक IP और DNS सर्वर जानकारी की खोज — नेटवर्क स्कैन के संकेत।", hackerLog: { title: "network_recon.txt", lines: [ { log: "IPv4 Address. . . . . . : 192.168.10.45", desc: "💡 पीड़ित PC का आंतरिक IP पता।" }, { log: "Default Gateway . . . . : 192.168.10.1", desc: "💡 नेटवर्क से बाहर जाने का मार्ग खोज रहा है।" }, { log: "DNS Servers . . . . . . : 192.168.10.10", desc: "💡 कॉर्पोरेट नेटवर्क में DNS सर्वर आमतौर पर Domain Controller (राजा) होता है। लक्ष्य मिला!" } ] }, terms: [ { name: "ipconfig /all", desc: "PC का IP, गेटवे, DNS सर्वर और सभी नेटवर्क सेटिंग्स दिखाने वाला कमांड।" }, { name: "Domain Controller", desc: "कंपनी नेटवर्क के सभी खातों और अनुमतियों का केंद्रीय प्रबंधन करने वाला मुख्य सर्वर (सिंहासन)।" } ] },
      { title: "हमले का मार्ग खोज", feynman: "दसों हज़ार निवासियों की जाँच करके वंशवृक्ष बनाना! राजा तक पहुँचने का सबसे तेज़ और गुप्त रास्ता खोजना।", expert: "Active Directory में वस्तुओं के बीच अनुमति संबंधों (ACL, सत्र) को BloodHound से विज़ुअलाइज़ करना।", defTooltip: "🚨 कम समय में Active Directory सूचना (LDAP) की भारी मात्रा में पूछताछ!", hackerLog: { title: "SharpHound_Log_Analyzer.txt", lines: [ { log: "[+] Enumerating trusts for domain...", desc: "💡 डोमेन प्रणालियों के बीच विश्वास संबंध (अनुमति श्रृंखला) मैप कर रहा है।" }, { log: "[+] Collecting Local Admin, Sessions...", desc: "💡 सभी PC पर स्थानीय व्यवस्थापक अधिकार और लॉग-इन सत्र एकत्र कर रहा है।" }, { log: "[+] Found 1500 Computers, 500 Users.", desc: "💡 पूरा संगठनात्मक चार्ट और इंफ्रास्ट्रक्चर अनुमति मानचित्र प्राप्त!" }, { log: "[+] Compressing data to BloodHound.zip", desc: "💡 विशाल अनुमति मानचित्र को एक zip फ़ाइल में संपीड़ित कर रहा है।" } ] }, terms: [ { name: "SharpHound.exe", desc: "डोमेन में हज़ारों PC और उपयोगकर्ताओं के बीच सभी अनुमति संबंधों (AD) को एकत्र करने वाला टोही उपकरण।" }, { name: "BloodHound", desc: "एकत्र किए गए डेटा से Domain Admin तक का सबसे छोटा हमला मार्ग मैप करने वाला विज़ुअलाइज़ेशन टूल।" } ] },
      { title: "लक्ष्य पहचाना गया", feynman: "एच्लीस की एड़ी मिली! रोबोट पहरेदार (सेवा खाता) लापरवाही से मास्टर चाबी लिए घूम रहा था।", expert: "पुराने पासवर्ड और अत्यधिक विशेषाधिकार (Domain Admin) वाले सेवा खाते की पहचान की।", defTooltip: "🎯 कमज़ोर सेवा खाते की ओर असामान्य पहुँच पैटर्न पर नज़र।", hackerLog: { title: "attack_path_analysis.txt", lines: [ { log: "Node 1: USER Alice@corp.local", desc: "💡 हमारा वर्तमान पैर जमाव — Alice का अपहृत PC।" }, { log: "Node 2: GROUP IT_Support [MemberOf]", desc: "💡 Alice IT सपोर्ट समूह से संबंधित है — अनुमति की कड़ी।" }, { log: "Node 3: USER SVC_SQL [AdminTo]", desc: "💡 IT सपोर्ट SVC_SQL सेवा खाते का प्रबंधन कर सकता है। लक्ष्य पुष्ट!" } ] }, terms: [ { name: "Service Account", desc: "स्वचालित कार्यों के लिए सिस्टम या एप्लिकेशन द्वारा उपयोग किया जाने वाला खाता — अक्सर खराब प्रबंधित।" }, { name: "Domain Admin", desc: "डोमेन में सभी कंप्यूटर और सर्वर को नियंत्रित करने वाला सर्वोच्च व्यवस्थापक विशेषाधिकार।" } ] },
      { title: "Kerberoasting", feynman: "हैकर बेधड़क पहरेदार के पास जाता है: 'मुझे रोबोट पहरेदार से बात करने का पास चाहिए।' यह वैध प्रक्रिया है, इसलिए सभी धोखा खा जाते हैं।", expert: "Kerberos TGS अनुरोध एक सामान्य प्रमाणीकरण प्रक्रिया है, इसलिए यह फ़ायरवॉल से बिना पकड़े गुज़र जाती है।", defTooltip: "⚠️ Event ID 4769: इस उपयोगकर्ता को असामान्य सेवा टिकट (TGS) जारी किया गया।", hackerLog: { title: "kerberoast_request.txt", lines: [ { log: "[*] Action: Kerberoasting", desc: "💡 SVC_SQL से संवाद के लिए केंद्रीय सर्वर से 'वैध पास' का अनुरोध।" }, { log: "[*] Target User : SVC_SQL", desc: "💡 कमज़ोर खाते को सटीक रूप से निशाना बनाकर सर्वर को धोखा दे रहा है।" } ] }, terms: [ { name: "Kerberoasting", desc: "कमज़ोर सेवा खातों के प्रमाणीकरण टिकट गुप्त रूप से प्राप्त कर ऑफ़लाइन पासवर्ड क्रैक करने की हमला तकनीक।" }, { name: "TGS (Ticket Granting Service)", desc: "किसी विशिष्ट सेवा तक पहुँच अधिकृत करने वाला वैध टिकट।" } ] },
      { title: "टिकट निकाला गया", feynman: "पहरेदार एक बंद तिजोरी (पास) सौंपता है। इसके अंदर रोबोट पहरेदार का असली पासवर्ड एन्क्रिप्टेड रूप में छिपा है।", expert: "सेवा खाते के NTLM हैश से एन्क्रिप्ट किया गया TGS टिकट मेमोरी से सफलतापूर्वक निकाला गया।", defTooltip: "📦 सर्वर ने वैध प्रमाणीकरण टिकट जारी किया। अभी तक कोई स्पष्ट दुर्भावनापूर्ण गतिविधि नहीं।", hackerLog: { title: "hash_extracted.txt", lines: [ { log: "[+] Ticket successfully extracted!", desc: "💡 सर्वर ने बिना किसी संदेह के एन्क्रिप्टेड टिकट सौंप दिया।" }, { log: "[+] Hash: $krb5tgs$23$*SVC_SQL$...", desc: "💡 लक्ष्य खाते का असली पासवर्ड इस हैश वैल्यू में छिपा है।" } ] }, terms: [ { name: "NTLM Hash", desc: "विंडोज द्वारा उपयोगकर्ता पासवर्ड को सुरक्षित रखने के लिए उपयोग किया जाने वाला एन्क्रिप्टेड (हैश्ड) डेटा प्रारूप।" }, { name: "Memory Extraction", desc: "सुरक्षा उपकरणों से छिपकर सिस्टम मेमोरी (RAM) से एन्क्रिप्टेड क्रेडेंशियल चुराने की तकनीक।" } ] },
      { title: "ऑफ़लाइन क्रैकिंग", feynman: "हैकर तिजोरी को चुपके से अपने तहखाने में ले जाता है। कंपनी के कैमरों से दूर, सुपरकंप्यूटर से करोड़ों चाबियाँ आज़मा रहा है।", expert: "कॉर्पोरेट नेटवर्क के बाहर हैकर के निजी हार्डवेयर पर ब्रूट-फ़ोर्स — आंतरिक रूप से पूरी तरह अदृश्य।", defTooltip: "🔇 (पता लगाना असंभव) हैकर कॉर्पोरेट नेटवर्क के बाहर ऑफ़लाइन पासवर्ड क्रैक कर रहा है...", hackerLog: { title: "offline_cracking.txt", lines: [ { log: "Session..........: hashcat\nStatus...........: Running", desc: "💡 हैकर के शक्तिशाली GPU से चुराए गए हैश को क्रैक करना शुरू।" }, { log: "Speed.Dev.#1.....: 25000 kH/s", desc: "💡 प्रति सेकंड करोड़ों पासवर्ड संयोजन आज़मा रहा है। नेटवर्क से बाहर — पूरी तरह अदृश्य।" } ] }, terms: [ { name: "Hashcat", desc: "GPU कंप्यूटिंग शक्ति का उपयोग करके अत्यधिक गति से पासवर्ड हैश क्रैक करने वाला उपकरण।" }, { name: "Brute-force", desc: "पासवर्ड मिलने तक हर संभव अक्षर संयोजन आज़माते रहने वाला हमला।" } ] },
      { title: "पासवर्ड क्रैक हुआ", feynman: "खटाक! पहरेदार ने '1234' जैसा कमज़ोर ताला इस्तेमाल किया था, तिजोरी खुल गई। मास्टर चाबी अब हैकर के हाथ में है।", expert: "कमज़ोर पासवर्ड नीति का फ़ायदा उठाकर उच्च-विशेषाधिकार खाते के प्लेनटेक्स्ट क्रेडेंशियल प्राप्त किए।", defTooltip: "🔇 (पता लगाना असंभव) पासवर्ड क्रैक हो गया, लेकिन आंतरिक सिस्टम में कोई विफल लॉगिन लॉग नहीं।", hackerLog: { title: "cracked_password.txt", lines: [ { log: "$krb5tgs$23$*SVC_SQL$...:P@ssword123!", desc: "💡 बिंगो! लक्ष्य ने अनुमानित पासवर्ड इस्तेमाल किया — तिजोरी खुल गई।" }, { log: "[+] Cracking completed successfully.", desc: "💡 उच्च-विशेषाधिकार खाते का पासवर्ड पूरी तरह समझौता हो चुका है।" } ] }, terms: [ { name: "Plaintext Credential", desc: "अनएन्क्रिप्टेड पासवर्ड जिसे सीधे पढ़ा और सिस्टम लॉगिन के लिए उपयोग किया जा सकता है।" }, { name: "Password Complexity", desc: "बड़े-छोटे अक्षर, संख्या और विशेष वर्णों को मिलाने वाले सुरक्षा नियम।" } ] },
      { title: "डोमेन पर कब्ज़ा", feynman: "हैकर मास्टर चाबी से राजा के सिंहासन (Domain Controller) पर बैठ गया। अब इस किले का हर कंप्यूटर हैकर की मर्ज़ी से चलता है।", expert: "चुराए गए Domain Admin क्रेडेंशियल से WinRM के ज़रिए Domain Controller (DC) को रिमोट एक्सेस करके इंफ्रास्ट्रक्चर पर कब्ज़ा।", defTooltip: "🚨 गंभीर! सामान्य PC IP से Domain Controller (DC) पर Domain Admin रिमोट एक्सेस का प्रयास!", hackerLog: { title: "domain_takeover.txt", lines: [ { log: "[*] Connecting to 192.168.10.10 (DC01)", desc: "💡 क्रैक किए पासवर्ड से कंपनी के शीर्ष सर्वर — Domain Controller — को रिमोट एक्सेस।" }, { log: "[+] Successful login! Session established.", desc: "💡 लॉगिन सफल! कंपनी का हर PC और सर्वर अब हैकर के नियंत्रण में।" } ] }, terms: [ { name: "WinRM / evil-winrm", desc: "विंडोज रिमोट मैनेजमेंट प्रोटोकॉल का शोषण करके लक्ष्य सिस्टम पर रिमोट शेल खोलने वाला हैकिंग टूल।" }, { name: "Lateral Movement", desc: "हमलावर का प्रारंभिक अपहृत PC से नेटवर्क के अन्य सर्वरों और व्यवस्थापक कार्यस्थलों तक विस्तार।" } ] },
      { title: "रक्षा सक्रिय", feynman: "लेकिन किले का गुप्त निरीक्षक (GOTROOT) देख रहा था! जैसे ही हैकर सिंहासन पर पहुँचा, उसने फंदा फेंका — संचार काटा और घुसपैठिए को बाहर निकाला।", expert: "सुरक्षा निगरानी प्रणालियों ने लेटरल मूवमेंट का पता लगाया और रियल-टाइम में फ़ायरवॉल IP ब्लॉकिंग और खाता निष्क्रियण किया।", defTooltip: "🛡️ स्वचालित रक्षा सक्रिय: हमलावर के IP को पूरी तरह ब्लॉक और आइसोलेट करने के लिए फ़ायरवॉल नीतियाँ अपडेट।", hackerLog: { title: "connection_terminated.txt", lines: [ { log: "FATAL ERROR: Connection forcefully closed", desc: "💡 रक्षा प्रणाली (EDR/SIEM) ने असामान्य व्यवहार का पता लगाया और तुरंत कनेक्शन समाप्त किया।" }, { log: "IP 192.168.10.45 has been isolated.", desc: "💡 संक्रमित PC को नेटवर्क से पूरी तरह आइसोलेट किया गया। रक्षा सफल!" } ] }, terms: [ { name: "EDR & SIEM", desc: "एंडपॉइंट खतरों का पता लगाने वाला समाधान (EDR) और सुरक्षा लॉग को एकत्र और सह-संबद्ध करने वाली केंद्रीय प्रणाली (SIEM)।" }, { name: "Network Isolation", desc: "संक्रमित PC की नेटवर्क पहुँच को जबरन काटकर मैलवेयर को अन्य आंतरिक सिस्टम में फैलने से रोकना।" } ] }
    ]
