    texts: [
      { title: "初始访问", feynman: "员工不经意间打开的一封钓鱼邮件，就像打开城门的开关。恶意程序运行，黑客的远程控制终端就此悄然开启。", expert: "通过鱼叉式钓鱼邮件实现 Initial Access。C2 服务器连接已建立。", defTooltip: "👀 检测到来自未知外部 IP 的远程访问流量。", hackerLog: null, terms: [{name:"Spear Phishing", desc:"针对特定目标的定向钓鱼邮件攻击。"}, {name:"C2 Server", desc:"攻击者用于远程控制受感染系统的中央服务器。"}] },
      { title: "初始渗透", feynman: "入侵者照了照镜子。'我现在穿的是平民的衣服还是将军的盔甲？'他要搞清楚自己当前的权限等级。", expert: "识别被入侵会话的权限级别和组成员身份，以制定权限提升策略。", defTooltip: "⚠️ 普通用户执行了可疑命令 (whoami /all) 查询系统权限。", hackerLog: { title: "whoami_priv_check.txt", lines: [ { log: "USER INFORMATION\n----------------\nUser Name: CORP\\Alice", desc: "💡 确认被盗账户的身份信息。" }, { log: "GROUP INFORMATION\n...\nBUILTIN\\Users", desc: "💡 查看组成员身份以确定访问范围。" }, { log: "PRIVILEGES INFORMATION\n...\nSeChangeNotifyPrivilege", desc: "💡 寻找可利用的权限来提升至管理员。" } ] }, terms: [ { name: "whoami /all", desc: "Windows命令，显示当前用户的账户名、所属组和所有分配的权限。" }, { name: "Privilege Escalation", desc: "将普通用户权限提升至系统最高管理员权限的黑客攻击阶段。" } ] },
      { title: "内网侦察", feynman: "要攻城掠寨，首先需要地图。黑客拿出指南针和地图，确认国王（中央服务器）城堡的位置。", expert: "识别子网范围和DNS（通常是域控制器）IP，以绘制目标网络拓扑。", defTooltip: "🔍 检测到网络扫描行为——正在探测内网IP和DNS服务器信息。", hackerLog: { title: "network_recon.txt", lines: [ { log: "IPv4 Address. . . . . . : 192.168.10.45", desc: "💡 受害者PC在企业网络中的内部IP地址。" }, { log: "Default Gateway . . . . : 192.168.10.1", desc: "💡 发现网关——通向外部网络的出口。" }, { log: "DNS Servers . . . . . . : 192.168.10.10", desc: "💡 企业网络中DNS服务器通常就是域控制器（国王）。目标已发现！" } ] }, terms: [ { name: "ipconfig /all", desc: "显示PC的IP、网关、DNS服务器等所有网络配置信息的命令。" }, { name: "Domain Controller", desc: "集中管理公司网络中所有账户和权限的核心服务器（王座）。" } ] },
      { title: "攻击路径探索", feynman: "调查数万居民来制作族谱！寻找通往国王的最快最隐蔽的路径。", expert: "使用BloodHound可视化Active Directory中对象之间的权限关系（ACL、会话）。", defTooltip: "🚨 短时间内检测到大量Active Directory信息查询（LDAP）！", hackerLog: { title: "SharpHound_Log_Analyzer.txt", lines: [ { log: "[+] Enumerating trusts for domain...", desc: "💡 正在映射域系统之间的信任关系（权限链）。" }, { log: "[+] Collecting Local Admin, Sessions...", desc: "💡 收集所有PC上的本地管理员权限和登录会话（寻找跳板）。" }, { log: "[+] Found 1500 Computers, 500 Users.", desc: "💡 完整的组织架构图和基础设施权限地图已获取！" }, { log: "[+] Compressing data to BloodHound.zip", desc: "💡 将庞大的权限地图压缩成一个zip文件准备外传。" } ] }, terms: [ { name: "SharpHound.exe", desc: "扫描域内数千台PC和用户之间所有权限关系（AD）的侦察工具。" }, { name: "BloodHound", desc: "利用收集的数据绘制到Domain Admin最短攻击路径的可视化工具。" } ] },
      { title: "目标锁定", feynman: "阿喀琉斯之踵被发现了！机器人守卫（服务账户）不小心随身携带着万能钥匙。", expert: "发现了一个密码长期未更改且拥有过高权限（Domain Admin）的服务账户。", defTooltip: "🎯 正在监控针对脆弱服务账户的异常访问模式。", hackerLog: { title: "attack_path_analysis.txt", lines: [ { log: "Node 1: USER Alice@corp.local", desc: "💡 我们当前的立足点——Alice被入侵的PC。" }, { log: "Node 2: GROUP IT_Support [MemberOf]", desc: "💡 发现Alice属于IT支持组——一条权限链。" }, { log: "Node 3: USER SVC_SQL [AdminTo]", desc: "💡 IT支持组可以管理SVC_SQL服务账户。目标确认！" } ] }, terms: [ { name: "Service Account", desc: "系统或应用程序用于自动化任务的账户——通常管理不善容易被忽视。" }, { name: "Domain Admin", desc: "可以控制域中所有计算机和服务器的最高管理员权限。" } ] },
      { title: "Kerberoasting", feynman: "黑客大摇大摆地走向守卫：'嘿，我需要一张通行证去跟机器人守卫说话。'这是合法程序，所以所有人都上当了。", expert: "Kerberos TGS请求是正常的认证流程，因此可以不被检测地通过现有防火墙。", defTooltip: "⚠️ Event ID 4769：该用户获得了异常的服务票据（TGS）。", hackerLog: { title: "kerberoast_request.txt", lines: [ { log: "[*] Action: Kerberoasting", desc: "💡 向中央服务器请求与SVC_SQL通信的'合法通行证'。" }, { log: "[*] Target User : SVC_SQL", desc: "💡 精准瞄准脆弱账户来欺骗服务器。" } ] }, terms: [ { name: "Kerberoasting", desc: "秘密获取脆弱服务账户的认证票据并离线破解密码的攻击技术。" }, { name: "TGS (Ticket Granting Service)", desc: "证明访问特定服务授权的合法票据。" } ] },
      { title: "票据窃取", feynman: "守卫交出一个上锁的保险箱（通行证）。里面藏着机器人守卫的真实密码——以加密形式。", expert: "成功从内存中提取了使用服务账户NTLM哈希加密的TGS票据。", defTooltip: "📦 服务器签发了合法的认证票据。目前尚无明显恶意行为迹象。", hackerLog: { title: "hash_extracted.txt", lines: [ { log: "[+] Ticket successfully extracted!", desc: "💡 服务器毫无怀疑地交出了加密票据。" }, { log: "[+] Hash: $krb5tgs$23$*SVC_SQL$...", desc: "💡 目标账户的真实密码就隐藏在这个哈希值中。" } ] }, terms: [ { name: "NTLM Hash", desc: "Windows用于存储和保护用户密码的加密（哈希）数据格式。" }, { name: "Memory Extraction", desc: "直接访问系统内存（RAM）秘密窃取加密凭证的技术。" } ] },
      { title: "离线破解", feynman: "黑客把保险箱偷偷带回自己的地下室。远离公司的监控摄像头，用超级计算机尝试数亿把钥匙。", expert: "在黑客私人设备上进行暴力破解——在企业网络之外，内部完全无法检测。", defTooltip: "🔇 （无法检测）黑客正在企业网络外部离线破解密码...", hackerLog: { title: "offline_cracking.txt", lines: [ { log: "Session..........: hashcat\nStatus...........: Running", desc: "💡 开始用黑客强大的GPU破解窃取的哈希。" }, { log: "Speed.Dev.#1.....: 25000 kH/s", desc: "💡 每秒尝试数千万个密码组合。在网络外部——完全无法检测。" } ] }, terms: [ { name: "Hashcat", desc: "利用GPU计算能力以极高速度破解密码哈希的工具。" }, { name: "Brute-force", desc: "不断尝试所有可能的字符组合直到密码被破解的攻击方式。" } ] },
      { title: "密码破解完成", feynman: "咔嗒！守卫用的是'1234'这样的简单锁，保险箱轻松打开。万能钥匙现在在黑客手中。", expert: "利用弱密码策略的漏洞获取了高权限账户的明文凭证。", defTooltip: "🔇 （无法检测）密码已被破解，但内部系统中没有任何登录失败日志。", hackerLog: { title: "cracked_password.txt", lines: [ { log: "$krb5tgs$23$*SVC_SQL$...:P@ssword123!", desc: "💡 中了！目标使用了可预测的密码——保险箱已打开。" }, { log: "[+] Cracking completed successfully.", desc: "💡 高权限账户的密码已被完全破解。" } ] }, terms: [ { name: "Plaintext Credential", desc: "未加密的密码，可以直接读取并用于登录系统。" }, { name: "Password Complexity", desc: "强制混合大小写字母、数字和特殊字符以抵御破解的安全规则。" } ] },
      { title: "域控制权夺取", feynman: "黑客用万能钥匙坐上了国王的宝座（域控制器）。现在城堡里的每台电脑都听从黑客的指挥。", expert: "使用窃取的Domain Admin凭证通过WinRM远程访问域控制器（DC），夺取基础设施完全控制权。", defTooltip: "🚨 严重警报！检测到从普通PC IP向域控制器（DC）发起的Domain Admin远程访问！", hackerLog: { title: "domain_takeover.txt", lines: [ { log: "[*] Connecting to 192.168.10.10 (DC01)", desc: "💡 使用破解的密码远程访问公司顶级服务器——域控制器。" }, { log: "[+] Successful login! Session established.", desc: "💡 登录成功！公司的每台PC和服务器现在都在黑客掌控之下。" } ] }, terms: [ { name: "WinRM / evil-winrm", desc: "利用Windows远程管理协议在目标系统上打开远程Shell的黑客工具。" }, { name: "Lateral Movement", desc: "攻击者从最初被入侵的PC扩展到网络中其他服务器和管理员工作站的过程。" } ] },
      { title: "防御启动", feynman: "但城堡的秘密巡查官（GOTROOT）一直在监视！就在黑客要坐上宝座的那一刻，他抛出绳索——切断通信，将入侵者驱逐出去。", expert: "安全监控系统检测到横向移动，实时执行了防火墙IP封锁和账户停用措施。", defTooltip: "🛡️ 自动防御启动：防火墙策略已更新，攻击者IP已被完全封锁和隔离。", hackerLog: { title: "connection_terminated.txt", lines: [ { log: "FATAL ERROR: Connection forcefully closed", desc: "💡 防御系统（EDR/SIEM）检测到异常行为并立即终止了连接。" }, { log: "IP 192.168.10.45 has been isolated.", desc: "💡 受感染PC已从网络中完全隔离。防御成功！" } ] }, terms: [ { name: "EDR & SIEM", desc: "检测终端威胁的解决方案（EDR）和集中聚合分析企业安全日志的中央系统（SIEM）。" }, { name: "Network Isolation", desc: "强制切断受感染PC的网络访问以防止恶意软件传播到其他内部系统。" } ] }
    ]
