      { title: "ドメイン掌握", feynman: "ハッカーがマスターキーで王の玉座（ドメインコントローラー）に座りました。今やこの城のすべてのコンピューターがハッカーの意のままです。", expert: "窃取したDomain Admin認証情報でWinRMを介してドメインコントローラー（DC）にリモートアクセスし、インフラを完全に掌握。", defTooltip: "🚨 重大！一般PC IPからドメインコントローラー（DC）へのDomain Adminリモートアクセス試行を検出！", hackerLog: { title: "domain_takeover.txt", lines: [ { log: "[*] Connecting to 192.168.10.10 (DC01)", desc: "💡 解読したパスワードで会社最上位のサーバー ─ ドメインコントローラーにリモート接続。" }, { log: "[+] Successful login! Session established.", desc: "💡 ログイン成功！会社のすべてのPCとサーバーがハッカーの支配下に。" } ] }, terms: [ { name: "WinRM / evil-winrm", desc: "Windowsリモート管理プロトコルを悪用してターゲットシステムにリモートシェルを開くハッキングツール。" }, { name: "Lateral Movement", desc: "攻撃者が最初に侵害したPCからネットワーク内の他のサーバーや管理者端末へ侵入を拡大する行為。" } ] },
      { title: "防御発動", feynman: "しかし城の隠密検察官（GOTROOT）が見ていました！ハッカーが玉座に手を伸ばした瞬間、縄を投げて通信を切断し、侵入者を追い出します。", expert: "セキュリティ監視システムがラテラルムーブメントを検知し、リアルタイムでファイアウォールIP遮断とアカウント無効化を実施。", defTooltip: "🛡️ 自動防御発動：ファイアウォールポリシーを更新し、攻撃者のIPを完全にブロック・隔離。", hackerLog: { title: "connection_terminated.txt", lines: [ { log: "FATAL ERROR: Connection forcefully closed", desc: "💡 防御システム（EDR/SIEM）が異常行動を検知し即座に接続を強制終了。" }, { log: "IP 192.168.10.45 has been isolated.", desc: "💡 感染したPCがネットワークから完全に隔離されました。防御成功！" } ] }, terms: [ { name: "EDR & SIEM", desc: "エンドポイント脅威を検知するソリューション（EDR）と企業全体のセキュリティログを集約・相関分析する中央システム（SIEM）。" }, { name: "Network Isolation", desc: "感染PCのネットワークアクセスを強制的に切断し、マルウェアが他の内部システムに拡散するのを防止する措置。" } ] }
